</style>
<div class="lab-widget">
  <div class="stage-wrap">
    <svg id="stage" viewBox="0 0 680 360" xmlns="http://www.w3.org/2000/svg">
      <!-- 网格线 -->
      <g id="grid" stroke="var(--line)" stroke-width="0.5" opacity="0.4">
        <line x1="40" y1="0" x2="40" y2="360"/>
        <line x1="120" y1="0" x2="120" y2="360"/>
        <line x1="200" y1="0" x2="200" y2="360"/>
        <line x1="280" y1="0" x2="280" y2="360"/>
        <line x1="360" y1="0" x2="360" y2="360"/>
        <line x1="440" y1="0" x2="440" y2="360"/>
        <line x1="520" y1="0" x2="520" y2="360"/>
        <line x1="600" y1="0" x2="600" y2="360"/>
        <line x1="0" y1="40" x2="680" y2="40"/>
        <line x1="0" y1="120" x2="680" y2="120"/>
        <line x1="0" y1="200" x2="680" y2="200"/>
        <line x1="0" y1="280" x2="680" y2="280"/>
      </g>
      <!-- 抛物线 f(x)=x^2 映射：x∈[-2,2] → px∈[40,640], y∈[0,4] → py∈[340,20] -->
      <path id="parabola" d="M 40 340 Q 340 20 640 340" fill="none" stroke="var(--line)" stroke-width="1.5" opacity="0.6"/>
      <!-- 坐标轴 -->
      <line x1="40" y1="340" x2="640" y2="340" stroke="var(--text2)" stroke-width="1" opacity="0.5"/>
      <line x1="340" y1="20" x2="340" y2="360" stroke="var(--text2)" stroke-width="1" opacity="0.5"/>
      <!-- 刻度标签 -->
      <text x="40" y="358" fill="var(--text2)" font-size="10" font-family="var(--mono)" text-anchor="middle">-2</text>
      <text x="340" y="358" fill="var(--text2)" font-size="10" font-family="var(--mono)" text-anchor="middle">0</text>
      <text x="640" y="358" fill="var(--text2)" font-size="10" font-family="var(--mono)" text-anchor="middle">2</text>
      <text x="24" y="24" fill="var(--text2)" font-size="11" font-family="var(--mono)">f(x)=x²</text>
      <!-- 动态轨迹组：点、箭头、轨迹线、标注 -->
      <g id="trajectory">
        <path id="tracePath" fill="none" stroke="var(--accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/>
        <!-- 点由 js 动态生成 -->
      </g>
      <!-- 当前步标注 -->
      <text id="stepLabel" x="16" y="340" fill="var(--accent)" font-size="13" font-family="var(--mono)" font-variant-numeric="tabular-nums"/>
    </svg>
  </div>
  <div class="controls">
    <div class="ctrl-group">
      <label for="x0">起点 x₀</label>
      <input type="range" id="x0" min="-2.0" max="2.0" step="0.01" value="1.5">
      <span class="val mono" id="x0Val">1.50</span>
    </div>
    <div class="ctrl-group">
      <label for="lr">学习率 η</label>
      <input type="range" id="lr" min="0.01" max="0.5" step="0.01" value="0.1">
      <span class="val mono" id="lrVal">0.10</span>
    </div>
    <div class="ctrl-group">
      <label for="steps">步数</label>
      <input type="range" id="steps" min="0" max="20" step="1" value="5">
      <span class="val mono" id="stepsVal">5</span>
    </div>
    <div class="btn-group">
      <button id="stepBack" title="后退一步">◀</button>
      <button id="stepForward" class="prim" title="前进一步">▶</button>
      <button id="reset" title="重置到起点">⟲</button>
    </div>
  </div>
  <div class="readout-row">
    <span>当前步: <span class="mono accent" id="currentStepDisplay">0</span> / <span class="mono" id="totalStepsDisplay">5</span></span>
    <span>当前位置 x: <span class="mono accent" id="currentXDisplay">—</span></span>
    <span>f(x): <span class="mono accent" id="currentFDisplay">—</span></span>
  </div>
</div>
<script>
  (function() {
    const root = document.documentElement;
    const tok = n => getComputedStyle(root).getPropertyValue(n).trim();

    // state
    let x0 = 1.5;
    let learningRate = 0.1;
    let steps = 5;
    let currentStep = 5; // 初始显示5步

    // DOM refs
    const svg = document.getElementById('stage');
    const tracePath = document.getElementById('tracePath');
    const stepLabel = document.getElementById('stepLabel');
    const x0Input = document.getElementById('x0');
    const x0Val = document.getElementById('x0Val');
    const lrInput = document.getElementById('lr');
