    const stepsInput = document.getElementById('steps');
    const stepsVal = document.getElementById('stepsVal');
    const currentStepDisplay = document.getElementById('currentStepDisplay');
    const totalStepsDisplay = document.getElementById('totalStepsDisplay');
    const currentXDisplay = document.getElementById('currentXDisplay');
    const currentFDisplay = document.getElementById('currentFDisplay');
    const stepBackBtn = document.getElementById('stepBack');
    const stepForwardBtn = document.getElementById('stepForward');
    const resetBtn = document.getElementById('reset');

    // 坐标映射: x ∈ [-2, 2] → px ∈ [40, 640]; y ∈ [0, 4] → py ∈ [340, 20]
    function xToPx(x) { return 40 + (x + 2) / 4 * 600; }
    function yToPy(y) { return 340 - y / 4 * 320; }
    function f(x) { return x * x; }

    // 计算梯度下降序列
    function computeTrajectory(x0, lr, n) {
      const pts = [];
      let x = x0;
      for (let i = 0; i <= n; i++) {
        pts.push({ x: x, y: f(x), step: i });
        x = x - lr * 2 * x; // 梯度: 2x
      }
      return pts;
    }

    // 单一 update()
    function update() {
      const pts = computeTrajectory(x0, learningRate, steps);
      const showSteps = Math.min(currentStep, steps);
      const visiblePts = pts.slice(0, showSteps + 1);

      // 构建轨迹路径
      let d = '';
      if (visiblePts.length > 0) {
        d = `M ${xToPx(visiblePts[0].x)} ${yToPy(visiblePts[0].y)}`;
        for (let i = 1; i < visiblePts.length; i++) {
          d += ` L ${xToPx(visiblePts[i].x)} ${yToPy(visiblePts[i].y)}`;
        }
      }
      tracePath.setAttribute('d', d);

      // 清除旧点/箭头/标注 (保留 tracePath 和 stepLabel)
      const g = document.getElementById('trajectory');
      // 移除所有子元素除了 tracePath 和 stepLabel
      const children = g.children;
      const toRemove = [];
      for (let i = 0; i < children.length; i++) {
        const el = children[i];
        if (el.id !== 'tracePath' && el.id !== 'stepLabel') {
          toRemove.push(el);
        }
      }
      toRemove.forEach(el => el.remove());

      // 绘制点、箭头、标注
      const accent = tok('--accent');
      const ink = tok('--ink');
      const text2 = tok('--text2');
      const bg = tok('--bg');
      const line = tok('--line');

      for (let i = 0; i < visiblePts.length; i++) {
        const pt = visiblePts[i];
        const cx = xToPx(pt.x);
        const cy = yToPy(pt.y);
        const isFirst = (i === 0);
        const isLast = (i === visiblePts.length - 1);

        // 点
        const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        circle.setAttribute('cx', cx);
        circle.setAttribute('cy', cy);
        circle.setAttribute('r', isFirst ? 6 : (isLast ? 6 : 4));
        circle.setAttribute('fill', isFirst ? accent : (isLast ? 'var(--accent)' : 'var(--ink)'));
        circle.setAttribute('stroke', isFirst || isLast ? 'var(--bg)' : 'none');
        circle.setAttribute('stroke-width', '2');
        if (isLast) {
          circle.setAttribute('fill', 'var(--accent)');
          // 星形标记用 path 代替
          const star = document.createElementNS('http://www.w3.org/2000/svg', 'path');
          const s = 8;
          const starD = `M ${cx} ${cy-s} L ${cx+s*0.224} ${cy-s*0.309} L ${cx+s*0.951} ${cy-s*0.309} L ${cx+s*0.363} ${cy+s*0.118} L ${cx+s*0.588} ${cy+s*0.809} L ${cx} ${cy+s*0.382} L ${cx-s*0.588} ${cy+s*0.809} L ${cx-s*0.363} ${cy+s*0.118} L ${cx-s*0.951} ${cy-s*0.309} L ${cx-s*0.224} ${cy-s*0.309} Z`;
          star.setAttribute('d', starD);
